<section class="card narrow"><div class="auth-heading"><p class="eyebrow"><?= $e($ticket['client_name']) ?></p><h1><?= $e($title) ?></h1><p class="muted"><?= $ticket['intent']==='LINK'?'扫码确认，将微信绑定到当前账号。':'验证你的身份，继续访问应用。' ?></p></div><?php if($error): ?><p class="error" role="alert"><?= $e($error) ?></p><?php endif ?><div class="tabs" role="tablist" aria-label="登录方式"><?php if($wechatEnabled): ?><button id="tab-qr" type="button" role="tab" aria-controls="qr" aria-selected="<?= $tab==='qr'?'true':'false' ?>" data-tab="qr"><?= $icon('qr') ?>微信扫码</button><?php endif ?><?php if($ticket['intent']==='LOGIN'): ?><button id="tab-password" type="button" role="tab" aria-controls="password" aria-selected="<?= !$wechatEnabled||$tab==='password'?'true':'false' ?>" data-tab="password"><?= $icon('key') ?>账号密码</button><?php endif ?></div>
<?php if($wechatEnabled): ?><div id="qr" role="tabpanel" aria-labelledby="tab-qr" data-panel data-active="<?= $tab==='qr'?'1':'0' ?>"><div class="qr" data-qr data-ticket="<?= $e($ticket['id']) ?>" data-key="<?= $e($qrKey) ?>" data-expires="<?= $e($ticket['expires_at']) ?>"><img width="240" height="240" alt="微信小程序登录码" hidden><p data-qr-message role="status">正在获取小程序码…</p></div><p class="muted center">微信扫一扫，在小程序中确认<?= $ticket['intent']==='LINK'?'绑定':'登录' ?></p><p class="countdown center" data-countdown></p><form method="post" action="/login/refresh"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="request" value="<?= $e($ticket['id']) ?>"><button class="secondary" type="submit">刷新登录码</button></form><form id="qr-finish" method="post" action="/login/finish"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="request" value="<?= $e($ticket['id']) ?>"></form></div><?php endif ?>
<?php if($ticket['intent']==='LOGIN'): ?><form id="password" role="tabpanel" aria-labelledby="tab-password" data-panel data-active="<?= !$wechatEnabled||$tab==='password'?'1':'0' ?>" method="post" action="/login/password"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="request" value="<?= $e($ticket['id']) ?>"><label>邮箱或账号<input name="username" placeholder="请输入邮箱或账号" autocomplete="username" required maxlength="191"></label><label>密码<input name="password" placeholder="请输入账号密码" type="password" autocomplete="current-password" required maxlength="72"></label><button class="full-width" type="submit">登录并继续<?= $icon('arrow') ?></button><div class="auth-links"><a href="/register?request=<?= $e(urlencode($ticket['id'])) ?>">注册账号</a><a href="/forgot-password">忘记密码？</a></div></form><?php endif ?>
<form class="cancel-request" method="post" action="/login/cancel"><input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="request" value="<?= $e($ticket['id']) ?>"><button class="text" type="submit">取消本次请求</button></form><p class="auth-privacy">继续前可阅读<a href="/privacy">账号与隐私说明</a></p></section>
